typedef struct {
    char *name;
    char path[PATH_MAX];
    struct stat st;
    bool is_dir;
    bool is_link;
    bool is_exec;
    bool selected;
} Entry;

typedef struct {
    bool show_hidden;
    bool detail;
    bool no_rollover;
    bool no_auto_advance;
    bool null_sep;
    char sort_key; /* 0 default, s/e/t/a/d/v, r reverse */
    char *selection_file;
} Options;

typedef struct {
    Entry *entries;
    size_t count, cap;
    char cwd[PATH_MAX];
    int cur;
    int top;
    int rows, cols;
    char filter[256];
    Options opt;
    struct termios orig_termios;
    bool raw_enabled;
    bool alt_enabled;
    char **selected_paths;
    size_t nsel, csel;
} App;

static App *g_app;

static void die_cleanup(void);

static void xwrite(const char *s) {
    if (s) write(STDOUT_FILENO, s, strlen(s));
}

static void xprintf(const char *fmt, ...) {
    char buf[8192];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n > 0) write(STDOUT_FILENO, buf, (size_t)((n < (int)sizeof(buf)) ? n : (int)sizeof(buf)));
}

static void print_usage(void) { fputs(usage_text, stdout); }

static void free_entries(App *a) {
    if (!a) return;
    for (size_t i = 0; i < a->count; ++i) free(a->entries[i].name);
    free(a->entries);
    a->entries = NULL; a->count = a->cap = 0;
}

static void free_selections(App *a) {
    for (size_t i = 0; i < a->nsel; ++i) free(a->selected_paths[i]);
    free(a->selected_paths); a->selected_paths = NULL; a->nsel = a->csel = 0;
}

static void enter_alt(App *a) {
    if (a->alt_enabled) return;
    xprintf("\033[?1049h\033[22;0;0t\033[1;%dr\033(B\033[m\033[4l\033[?7h\033[?1h\033=\033[?1006;1000h\033[?25l\033[39;49m\033[39;49m\033(B\033[m", a->rows ? a->rows : 24);
    a->alt_enabled = true;
}

static void leave_alt(App *a) {
    if (!a || !a->alt_enabled) return;
    xprintf("\033[?1006;1000l\033[%d;1H\033[?12l\033[?25h\033[?1049l\033[23;0;0t\r\033[?1l\033>", a->rows ? a->rows : 24);
    a->alt_enabled = false;
}

static void enable_raw(App *a) {
    if (tcgetattr(STDIN_FILENO, &a->orig_termios) == 0) {
        struct termios raw = a->orig_termios;
        raw.c_iflag &= ~(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= ~(OPOST);
        raw.c_cflag |= (CS8);
        raw.c_lflag &= ~(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN] = 1;
        raw.c_cc[VTIME] = 0;
        if (tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw) == 0) a->raw_enabled = true;
    }
}

static void disable_raw(App *a) {
    if (a && a->raw_enabled) {
        tcsetattr(STDIN_FILENO, TCSAFLUSH, &a->orig_termios);
        a->raw_enabled = false;
    }
}

static void die_cleanup(void) {
    if (g_app) {
        leave_alt(g_app);
        disable_raw(g_app);
    }
}

static void on_signal(int sig) {
    (void)sig;
    die_cleanup();
    _exit(1);
}

static void update_size(App *a) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col && ws.ws_row) {
        a->rows = ws.ws_row;
        a->cols = ws.ws_col;
    } else {
        char *c = getenv("COLUMNS"), *l = getenv("LINES");
        a->cols = c ? atoi(c) : 80;
        a->rows = l ? atoi(l) : 24;
        if (a->cols <= 0) a->cols = 80;
        if (a->rows <= 0) a->rows = 24;
    }
}

static int mkdir_p(const char *path) {
    char tmp[PATH_MAX];
    size_t len = strlen(path);
    if (len >= sizeof(tmp)) return -1;
    strcpy(tmp, path);
    if (len > 1 && tmp[len-1] == '/') tmp[len-1] = '\0';
    for (char *p = tmp + 1; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, 0777) && errno != EEXIST) return -1;
            *p = '/';
        }
    }
    if (mkdir(tmp, 0777) && errno != EEXIST) return -1;
    return 0;
}

static void path_join(char *out, size_t sz, const char *dir, const char *name) {
    if (strcmp(dir, "/") == 0) snprintf(out, sz, "/%s", name);
    else snprintf(out, sz, "%s/%s", dir, name);
}

static char *xstrdup(const char *s) {
    char *p = strdup(s ? s : "");
    if (!p) { perror("strdup"); exit(2); }
    return p;
}

static int digit_val(int c) { return c >= '0' && c <= '9'; }

static int natural_cmp(const char *a, const char *b, bool foldcase) {
    const unsigned char *pa = (const unsigned char*)a, *pb = (const unsigned char*)b;
    while (*pa && *pb) {
        if (digit_val(*pa) && digit_val(*pb)) {
            while (*pa == '0') pa++;
            while (*pb == '0') pb++;
            const unsigned char *sa = pa, *sb = pb;
            while (digit_val(*pa)) pa++;
            while (digit_val(*pb)) pb++;
            int la = (int)(pa - sa), lb = (int)(pb - sb);
            if (la != lb) return (la < lb) ? -1 : 1;
            int r = strncmp((const char*)sa, (const char*)sb, (size_t)la);
            if (r) return r;
            continue;
        }
        int ca = *pa++, cb = *pb++;
        if (foldcase) { ca = tolower(ca); cb = tolower(cb); }
        if (ca != cb) return ca < cb ? -1 : 1;
    }
    if (*pa) return 1;
    if (*pb) return -1;
    return 0;
}

static const char *extension_of(const char *s) {
    const char *dot = strrchr(s, '.');
    if (!dot || dot == s) return "";
    return dot + 1;
}

static char g_sort_key;

static int entry_cmp(const void *va, const void *vb) {
    const Entry *a = (const Entry*)va, *b = (const Entry*)vb;
    if (a->is_dir != b->is_dir) return a->is_dir ? -1 : 1;
    int r = 0;
    switch (g_sort_key) {
        case 's':
            if (a->st.st_size != b->st.st_size) r = (a->st.st_size > b->st.st_size) ? -1 : 1;
            break;
        case 'e': {
            r = natural_cmp(extension_of(a->name), extension_of(b->name), true);
            if (!r) r = natural_cmp(a->name, b->name, false);
            break;
        }
        case 't':
        case 'a':
        case 'd':
            if (a->st.st_mtime != b->st.st_mtime) r = (a->st.st_mtime < b->st.st_mtime) ? -1 : 1;
            break;
        case 'v':
            r = natural_cmp(a->name, b->name, true);
            break;
        default:
            r = natural_cmp(a->name, b->name, false);
            break;
    }
    if (!r) r = natural_cmp(a->name, b->name, false);
    if (g_sort_key == 'r') r = -r;
    return r;
}

static bool selected_contains(App *a, const char *path) {
    for (size_t i = 0; i < a->nsel; ++i) if (strcmp(a->selected_paths[i], path) == 0) return true;
    return false;
}

static void selected_add(App *a, const char *path) {
    if (selected_contains(a, path)) return;
    if (a->nsel == a->csel) {
        a->csel = a->csel ? a->csel * 2 : 16;
        a->selected_paths = realloc(a->selected_paths, a->csel * sizeof(char*));
        if (!a->selected_paths) exit(2);
    }
    a->selected_paths[a->nsel++] = xstrdup(path);
}

static void selected_remove(App *a, const char *path) {
    for (size_t i = 0; i < a->nsel; ++i) {
        if (strcmp(a->selected_paths[i], path) == 0) {
            free(a->selected_paths[i]);
            memmove(&a->selected_paths[i], &a->selected_paths[i+1], (a->nsel-i-1)*sizeof(char*));
            a->nsel--;
            return;
        }
    }
}

static bool filter_match(App *a, const char *name) {
    if (!a->filter[0]) return true;
    char nbuf[PATH_MAX], fbuf[256];
    size_t i;
    for (i = 0; name[i] && i < sizeof(nbuf)-1; ++i) nbuf[i] = (char)tolower((unsigned char)name[i]);
    nbuf[i] = 0;
    for (i = 0; a->filter[i] && i < sizeof(fbuf)-1; ++i) fbuf[i] = (char)tolower((unsigned char)a->filter[i]);
    fbuf[i] = 0;
    return strstr(nbuf, fbuf) != NULL;
}

static int load_dir(App *a, const char *dir) {
    DIR *dp = opendir(dir);
    if (!dp) return -1;
    char real[PATH_MAX];
    if (realpath(dir, real)) strncpy(a->cwd, real, sizeof(a->cwd)-1);
    else strncpy(a->cwd, dir, sizeof(a->cwd)-1);
    a->cwd[sizeof(a->cwd)-1] = 0;
    free_entries(a);
    struct dirent *de;
    while ((de = readdir(dp))) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        if (!a->opt.show_hidden && de->d_name[0] == '.') continue;
        if (!filter_match(a, de->d_name)) continue;
        if (a->count == a->cap) {
            a->cap = a->cap ? a->cap * 2 : 64;
            a->entries = realloc(a->entries, a->cap * sizeof(Entry));
            if (!a->entries) exit(2);
        }
        Entry *e = &a->entries[a->count];
        memset(e, 0, sizeof(*e));
        e->name = xstrdup(de->d_name);
        path_join(e->path, sizeof(e->path), a->cwd, de->d_name);
        if (lstat(e->path, &e->st) != 0) memset(&e->st, 0, sizeof(e->st));
        e->is_link = S_ISLNK(e->st.st_mode);
        struct stat st2;
        if (stat(e->path, &st2) == 0) {
            e->is_dir = S_ISDIR(st2.st_mode);
            if (!e->is_link) e->st = st2;
        } else e->is_dir = S_ISDIR(e->st.st_mode);
        e->is_exec = !e->is_dir && (e->st.st_mode & (S_IXUSR|S_IXGRP|S_IXOTH));
        e->selected = selected_contains(a, e->path);
        a->count++;
    }
    closedir(dp);
    g_sort_key = a->opt.sort_key;
    qsort(a->entries, a->count, sizeof(Entry), entry_cmp);
    if (a->cur < 0) a->cur = 0;
    if ((size_t)a->cur >= a->count) a->cur = a->count ? (int)a->count - 1 : 0;
    if (a->top > a->cur) a->top = a->cur;
    return 0;
}

static void mode_string(mode_t m, char out[11]) {
    out[0] = S_ISDIR(m) ? 'd' : S_ISLNK(m) ? 'l' : S_ISCHR(m) ? 'c' : S_ISBLK(m) ? 'b' : S_ISFIFO(m) ? 'p' : S_ISSOCK(m) ? 's' : '-';
    const char *rwx = "rwxrwxrwx";
    for (int i = 0; i < 9; ++i) out[i+1] = (m & (1 << (8-i))) ? rwx[i] : '-';
    out[10] = 0;
}

static void size_string(off_t sz, char *out, size_t n) {
    double v = (double)sz;
    const char *units[] = {"B","K","M","G","T"};
    int u = 0;
    while (v >= 1024.0 && u < 4) { v /= 1024.0; u++; }
    if (u == 0) snprintf(out, n, "%lldB", (long long)sz);
    else if (v < 10) snprintf(out, n, "%.1f%s", v, units[u]);
    else snprintf(out, n, "%.0f%s", v, units[u]);
}

static void time_string(time_t t, char *out, size_t n) {
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(out, n, "%Y-%m-%d %H:%M", &tmv);
}

static void trim_print(const char *s, int max) {
    int len = (int)strlen(s);
    if (len <= max) { xwrite(s); return; }
    if (max <= 1) return;
    write(STDOUT_FILENO, s, (size_t)(max-1));
    xwrite("~");
}

static char mark_for(const Entry *e) {
    if (e->is_dir) return '/';
    if (e->is_link) return '@';
    if (e->is_exec) return '*';
    return '\0';
}

static char sort_flag(char k) {
    switch(k) { case 's': return 'S'; case 'e': return 'E'; case 't': return 'M'; case 'a': return 'A'; case 'd': return 'C'; case 'r': return 'R'; case 'v': return 'V'; default: return 0; }
}

static void draw(App *a) {
    update_size(a);
    int list_rows = a->rows - 3;
    if (list_rows < 1) list_rows = 1;
    if (a->cur < a->top) a->top = a->cur;
    if (a->cur >= a->top + list_rows) a->top = a->cur - list_rows + 1;
    xwrite("\033[H\033[2J");
    xwrite("\033[0;1;7m\033[34m1\033[39m\033[0m 2 3 4 5 6 7 8 \033[0;4m\033[34m");
    trim_print(a->cwd, a->cols > 20 ? a->cols - 18 : a->cols);
    xwrite("\033[0m");
    int row = 3;
    for (int i = a->top; i < (int)a->count && row <= a->rows-1; ++i, ++row) {
        Entry *e = &a->entries[i];
        xprintf("\033[%d;1H", row);
        bool cur = (i == a->cur);
        if (a->opt.detail) {
            char ts[32], sz[32], oct[8];
            time_string(e->st.st_mtime, ts, sizeof(ts));
            size_string(e->st.st_size, sz, sizeof(sz));
            snprintf(oct, sizeof(oct), "%03o", (unsigned)(e->st.st_mode & 0777));
            xwrite(cur ? "\033[0;1m>" : " ");
            xprintf("\033[0;2m%s  %s %7s \033[0m ", ts, oct, sz);
            if (e->selected) xwrite("+");
            if (cur) xwrite("\033[0;1;7m");
            else if (e->is_dir) xwrite("\033[34m");
            trim_print(e->name, a->cols - 35);
            char m = mark_for(e); if (m) xprintf("%c", m);
            xwrite("\033[0m");
        } else {
            xwrite(e->selected ? "\033[0;1;7m\033[34m+" : "\033[0;1m\033[34m ");
            if (cur) xwrite("\033[0;1;7m"); else xwrite("\033[0m");
            if (e->is_dir) xwrite("\033[34m");
            trim_print(e->name, a->cols - 3);
            char m = mark_for(e); if (m) xprintf("%c", m);
            xwrite("\033[0m");
        }
    }
    /* status */
    xprintf("\033[%d;1H\033[0m\033[34m", a->rows);
    if (a->count == 0) {
        xwrite("0/0");
    } else {
        Entry *e = &a->entries[a->cur];
        char ts[32], sz[32], mode[11];
        time_string(e->st.st_mtime, ts, sizeof(ts));
        size_string(e->st.st_size, sz, sizeof(sz));
        mode_string(e->st.st_mode, mode);
        char flags[32] = "";
        size_t fl = 0;
        if (a->opt.show_hidden) flags[fl++] = 'H';
        char sf = sort_flag(a->opt.sort_key); if (sf) flags[fl++] = sf;
        flags[fl] = 0;
        if (a->nsel)
            xprintf("%d/%zu %s+%zu  %s %s %s", a->cur+1, a->count, flags, a->nsel, ts, mode, sz);
        else if (flags[0])
            xprintf("%d/%zu %s %s %s %s", a->cur+1, a->count, flags, ts, mode, sz);
        else
            xprintf("%d/%zu  %s %s %s", a->cur+1, a->count, ts, mode, sz);
    }
    int crow = 3 + (a->cur - a->top);
    if (a->count && crow >= 3 && crow < a->rows) xprintf("\033[%d;1H", crow);
    xwrite("\033[39m\033(B\033[m");
    fsync(STDOUT_FILENO);
}

static int read_key(void) {
    unsigned char c;
    ssize_t n = read(STDIN_FILENO, &c, 1);
    if (n <= 0) return -1;
    if (c == 033) {
        unsigned char seq[8];
        int r = 0;
        /* in raw mode this blocks; script/tests send full sequences. */
        if (read(STDIN_FILENO, &seq[r], 1) <= 0) return 033;
        if (seq[0] != '[' && seq[0] != 'O') return 033;
        r++;
        if (read(STDIN_FILENO, &seq[r], 1) <= 0) return 033;
        if (seq[1] >= '0' && seq[1] <= '9') {
            unsigned char last;
            if (read(STDIN_FILENO, &last, 1) <= 0) return 033;
            if (seq[1]=='5') return 1005; /* PgUp */
            if (seq[1]=='6') return 1006; /* PgDn */
            return 033;
        }
        switch(seq[1]) { case 'A': return 1001; case 'B': return 1002; case 'C': return 1003; case 'D': return 1004; case 'H': return 'g'; case 'F': return 'G'; }
        return 033;
    }
    return c;
}

static void prompt_line(App *a, const char *prompt, char *buf, size_t bufsz) {
    size_t len = strlen(buf);
    xprintf("\033[%d;1H\033[2K\033[0m\033[34m%s%s  \b\b\033[0m", a->rows, prompt, buf);
    while (1) {
        int k = read_key();
        if (k == -1 || k == 033) { buf[0] = 0; break; }
        if (k == '\r' || k == '\n') break;
        if ((k == 127 || k == 8) && len) { buf[--len] = 0; xwrite("\b \b"); continue; }
        if (isprint(k) && len + 1 < bufsz) {
            buf[len++] = (char)k; buf[len] = 0;
            char ch[2] = {(char)k,0}; xwrite("\033[34m"); xwrite(ch); xwrite("  \b\b\033[0m");
        }
    }
}

static void show_help(App *a) {
    leave_alt(a);
    xwrite(help_body);
    xwrite("\r\nCONTEXTS\r\n 1* "); xwrite(a->cwd); xwrite("\r\n\r\n");
    xwrite("VOLUME: avail:0B used:0B size:0B\r\n\r\n");
    const char *home = getenv("HOME"); if (!home) home = "/home/agent";
    xprintf("SELECTION FILE: %s/.config/nnn/.selection\r\n\r\n", home);
    xwrite("v5.2\r\nBSD 2-Clause\r\nhttps://github.com/jarun/nnn\r\n");
    read_key();
    enter_alt(a);
}

static void go_parent(App *a) {
    if (strcmp(a->cwd, "/") == 0) return;
    char oldbase[NAME_MAX+1] = "";
    const char *slash = strrchr(a->cwd, '/');
    if (slash) strncpy(oldbase, slash+1, sizeof(oldbase)-1);
    char parent[PATH_MAX]; strncpy(parent, a->cwd, sizeof(parent)-1); parent[sizeof(parent)-1] = 0;
    char *p = strrchr(parent, '/');
    if (p && p != parent) *p = 0; else strcpy(parent, "/");
    a->cur = 0; a->top = 0; a->filter[0] = 0;
    if (load_dir(a, parent) == 0 && oldbase[0]) {
        for (size_t i = 0; i < a->count; ++i) if (strcmp(a->entries[i].name, oldbase) == 0) { a->cur = (int)i; break; }
    }
}

static void toggle_select(App *a) {
    if (!a->count) return;
    Entry *e = &a->entries[a->cur];
    if (selected_contains(a, e->path)) { selected_remove(a, e->path); e->selected = false; }
    else { selected_add(a, e->path); e->selected = true; }
    if (!a->opt.no_auto_advance && a->cur + 1 < (int)a->count) a->cur++;
}

static void select_all(App *a) {
    for (size_t i = 0; i < a->count; ++i) { selected_add(a, a->entries[i].path); a->entries[i].selected = true; }
}

static void output_selections(App *a) {
    if (!a->opt.selection_file || a->nsel == 0) return;
    FILE *fp = NULL;
    bool to_stdout = strcmp(a->opt.selection_file, "-") == 0;
    if (to_stdout) fp = stdout;
    else fp = fopen(a->opt.selection_file, "w");
    if (!fp) return;
    for (size_t i = 0; i < a->nsel; ++i) {
        fputs(a->selected_paths[i], fp);
        fputc(a->opt.null_sep ? '\0' : '\n', fp);
    }
    if (!to_stdout) fclose(fp);
}

static void handle_new(App *a) {
    char buf[PATH_MAX] = "";
    prompt_line(a, "[path/]name: ", buf, sizeof(buf));
    if (!buf[0]) return;
    char path[PATH_MAX]; path_join(path, sizeof(path), a->cwd, buf);
    size_t len = strlen(path);
    if (len && path[len-1] == '/') mkdir_p(path);
    else {
        char parent[PATH_MAX]; strncpy(parent, path, sizeof(parent)-1); parent[sizeof(parent)-1] = 0;
        char *s = strrchr(parent, '/'); if (s && s != parent) { *s = 0; mkdir_p(parent); }
        int fd = open(path, O_CREAT|O_EXCL|O_WRONLY, 0666); if (fd >= 0) close(fd);
    }
    load_dir(a, a->cwd);
}

static int run_app(App *a) {
    g_app = a;
    signal(SIGINT, on_signal); signal(SIGTERM, on_signal); signal(SIGWINCH, SIG_IGN);
    update_size(a);
    enable_raw(a);
    enter_alt(a);
    draw(a);
    int exit_code = 0;
    while (1) {
        int k = read_key();
        if (k < 0) { exit_code = 0; break; }
        if (k == 'q' || k == 17 || k == 7) { exit_code = 0; break; }
        if (k == 'Q') { exit_code = 1; break; }
        if (k == 'j' || k == 1002 || k == 4 || k == 1006) {
            int step = (k == 4 || k == 1006) ? (a->rows > 4 ? a->rows-4 : 1) : 1;
            if (a->count) {
                if (a->cur + step < (int)a->count) a->cur += step;
                else a->cur = a->opt.no_rollover ? (int)a->count-1 : 0;
            }
        } else if (k == 'k' || k == 1001 || k == 21 || k == 1005) {
            int step = (k == 21 || k == 1005) ? (a->rows > 4 ? a->rows-4 : 1) : 1;
            if (a->count) {
                if (a->cur - step >= 0) a->cur -= step;
                else a->cur = a->opt.no_rollover ? 0 : (int)a->count-1;
            }
        } else if (k == 'g' || k == 1) { a->cur = 0; }
        else if (k == 'G' || k == 5) { if (a->count) a->cur = (int)a->count-1; }
        else if (k == 'h' || k == 1004 || k == '-' || k == 127) { go_parent(a); }
        else if (k == 'l' || k == 1003 || k == '\r' || k == '\n') {
            if (a->count) {
                Entry *e = &a->entries[a->cur];
                if (e->is_dir) { char p[PATH_MAX]; strncpy(p, e->path, sizeof(p)-1); p[sizeof(p)-1]=0; a->cur=0; a->top=0; a->filter[0]=0; load_dir(a, p); }
                else if (a->opt.selection_file) { selected_add(a, e->path); exit_code = 0; break; }
            }
        } else if (k == 'H' || k == '.') { a->opt.show_hidden = !a->opt.show_hidden; a->cur=0; a->top=0; load_dir(a, a->cwd); }
        else if (k == 'd') { a->opt.detail = !a->opt.detail; }
        else if (k == ' ') { toggle_select(a); }
        else if (k == '+') { toggle_select(a); }
        else if (k == 'a') { select_all(a); }
        else if (k == 'A') {
            for (size_t i=0;i<a->count;i++) { if (selected_contains(a,a->entries[i].path)) selected_remove(a,a->entries[i].path); else selected_add(a,a->entries[i].path); }
            load_dir(a, a->cwd);
        }
        else if (k == '/') { a->filter[0]=0; prompt_line(a, "/", a->filter, sizeof(a->filter)); a->cur=0; a->top=0; load_dir(a, a->cwd); }
        else if (k == 12) { }
        else if (k == '?') { show_help(a); }
        else if (k == 'n') { handle_new(a); }
        else if (k == 't' || k == 'T') {
            xprintf("\033[%d;1H\033[2K\033[34msort [a/d/e/r/s/t/v]: \033[0m", a->rows);
            int sk = read_key();
            if (strchr("aders tv", sk)) { if (sk==' ') sk=0; a->opt.sort_key=(char)sk; load_dir(a,a->cwd); }
            else if (strchr("aertsvd", sk)) { a->opt.sort_key=(char)sk; load_dir(a,a->cwd); }
        }
        draw(a);
    }
    leave_alt(a);
    disable_raw(a);
    output_selections(a);
    return exit_code;
}

static void dirname_basename(const char *path, char *dir, size_t dsz, char *base, size_t bsz) {
    char tmp[PATH_MAX]; strncpy(tmp, path, sizeof(tmp)-1); tmp[sizeof(tmp)-1]=0;
    size_t len = strlen(tmp);
    while (len > 1 && tmp[len-1] == '/') tmp[--len] = 0;
    char *s = strrchr(tmp, '/');
    if (!s) { strncpy(dir, ".", dsz); strncpy(base, tmp, bsz); }
    else if (s == tmp) { strncpy(dir, "/", dsz); strncpy(base, s+1, bsz); }
    else { *s = 0; strncpy(dir, tmp, dsz); strncpy(base, s+1, bsz); }
    dir[dsz-1]=0; base[bsz-1]=0;
}

static void startup_prompt_new(App *a, const char *base) {
    char buf[PATH_MAX];
    strncpy(buf, base, sizeof(buf)-1); buf[sizeof(buf)-1]=0;
    prompt_line(a, "[path/]name: ", buf, sizeof(buf));
    if (!buf[0]) return;
    char path[PATH_MAX]; path_join(path, sizeof(path), a->cwd, buf);
    int fd = open(path, O_CREAT|O_EXCL|O_WRONLY, 0666); if (fd >= 0) close(fd);
    load_dir(a, a->cwd);
    for (size_t i=0;i<a->count;i++) if (strcmp(a->entries[i].name, buf)==0) { a->cur=(int)i; break; }
}

int main(int argc, char **argv) {
    Options opt; memset(&opt, 0, sizeof(opt));
    int c;
    opterr = 1;
    while ((c = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKnNoOp:P:QrRs:St:T:uUVxz0h")) != -1) {
        switch (c) {
            case 'h': print_usage(); return 0;
            case 'V': puts(VERSION); return 0;
            case 'H': opt.show_hidden = true; break;
            case 'd': opt.detail = true; break;
            case 'J': opt.no_auto_advance = true; break;
            case 'R': opt.no_rollover = true; break;
            case 'p': opt.selection_file = xstrdup(optarg); break;
            case '0': opt.null_sep = true; break;
            case 'T': if (optarg && strchr("aders tv", optarg[0])) opt.sort_key = optarg[0]; else if (optarg) opt.sort_key = optarg[0]; break;
            case 'F': {
                long v = strtol(optarg ? optarg : "0", NULL, 10);
                if (v > 1 || v < 0) return 1;
                break;
            }
            case 'K': return 0;
            case '?': print_usage(); return 1;
            default: break;
        }
    }

    if (!isatty(STDIN_FILENO) || !isatty(STDOUT_FILENO)) {
        fputs("0 entries\n", stderr);
        return 1;
    }

    App app; memset(&app, 0, sizeof(app));
    app.opt = opt; app.cur = 0; app.top = 0;
    update_size(&app);

    const char *start = (optind < argc) ? argv[optind] : ".";
    struct stat st;
    bool prompt_new = false;
    char newbase[PATH_MAX] = "";
    char opendir_path[PATH_MAX];

    if (stat(start, &st) == 0) {
        if (S_ISDIR(st.st_mode)) strncpy(opendir_path, start, sizeof(opendir_path)-1);
        else { dirname_basename(start, opendir_path, sizeof(opendir_path), newbase, sizeof(newbase)); prompt_new = false; }
    } else {
        size_t len = strlen(start);
        if (len && start[len-1] == '/') {
            mkdir_p(start);
            strncpy(opendir_path, start, sizeof(opendir_path)-1);
        } else {
            char dir[PATH_MAX]; dirname_basename(start, dir, sizeof(dir), newbase, sizeof(newbase));
            mkdir_p(dir);
            strncpy(opendir_path, dir, sizeof(opendir_path)-1);
            prompt_new = true;
        }
    }
    opendir_path[sizeof(opendir_path)-1] = 0;

    if (load_dir(&app, opendir_path) != 0) {
        fputs("0 entries\n", stderr);
        return 1;
    }
    g_app = &app;
    signal(SIGINT, on_signal); signal(SIGTERM, on_signal);
    enable_raw(&app);
    enter_alt(&app);
    if (prompt_new) {
        draw(&app);
        startup_prompt_new(&app, newbase);
    }
    int rc = run_app(&app);
    free_entries(&app);
    free_selections(&app);
    free(opt.selection_file);
    return rc;
}
