tmp=tempfile.mkdtemp(); open(os.path.join(tmp,'a'),'w').write('a'); os.mkdir(os.path.join(tmp,'d'))
for keys,args in [(b'q',[ './executable', tmp]), (b' aq',[ './executable','-p','-',tmp]), (b'?q',[ './executable', tmp])]:
